import { describe, expect, it } from 'vitest';
import { LiveGateway } from '../src/live-updates/LiveGateway.js';
import { EventFeedClient } from '../src/live-updates/EventFeedClient.js';

function fakeSocket(): { socket: WebSocket; received: string[] } {
  const received: string[] = [];
  const socket = {
    readyState: 1,
    send: (message: string) => {
      received.push(message);
    },
  };
  return { socket: socket as unknown as WebSocket, received };
}

describe('UC-004 Watch item live', () => {
  it.todo('REQ-007 AC1: manual: requires running two or more live update server instances, not practical in a unit test');

  it.todo('REQ-007 AC2: manual: requires deploying an additional instance without code change, not practical in a unit test');

  it('SEQ-004 scenario: Watch item live', () => {
    const { socket, received } = fakeSocket();
    const sockets = new Map<string, WebSocket>([['client-1', socket]]);
    const gateway = new LiveGateway(sockets);
    const eventFeedClient = new EventFeedClient(gateway);

    // 1. User -> LiveGateway: watch
    gateway.watch('client-1', 'item-1');

    // 2. EventFeed -> EventFeedClient: onEvent
    // 3. EventFeedClient -> LiveGateway: broadcast to watching browsers
    eventFeedClient.onEvent('bid', 'item-1:bid-42');
    expect(received.length).toBe(1);
    expect(received[0]).toContain('item-1');

    // 4. User -> LiveGateway: unwatch
    gateway.unwatch('client-1', 'item-1');
    eventFeedClient.onEvent('bid', 'item-1:bid-43');
    expect(received.length).toBe(1);
  });
});

