import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { DatabaseSync } from 'node:sqlite';
import { AuctionStatus } from '../src/auction-api/AuctionStatus.js';
import { Item } from '../src/auction-api/Item.js';
import { ItemService } from '../src/auction-api/ItemService.js';
import { BidService } from '../src/auction-api/BidService.js';
import { AuctionCloser } from '../src/auction-api/AuctionCloser.js';
import { ItemStore } from '../src/auction-api/ItemStore.js';
import { AuctionEventPublisher } from '../src/auction-api/AuctionEventPublisher.js';
import { BidEventPublisher } from '../src/auction-api/BidEventPublisher.js';
import { EventFeedClient } from '../src/live-updates/EventFeedClient.js';
import { LiveGateway } from '../src/live-updates/LiveGateway.js';
import { EventFeed } from '../src/auction-api/EventFeed.js';

const START = new Date('2030-01-01T00:00:00.000Z');
const END = new Date('2030-01-01T01:00:00.000Z');
const AFTER_END = new Date('2030-01-01T02:00:00.000Z');

function userStoreStub(): never {
  // A permissive stand-in: any lookup resolves to a user-like object.
  return new Proxy(
    {},
    { get: () => async () => ({ id: 'user' }) },
  ) as never;
}

function fakeSocket(): { send: ReturnType<typeof vi.fn>; readyState: number } {
  return { send: vi.fn(), readyState: 1 };
}

function build() {
  const db = new DatabaseSync(':memory:');
  const store = new ItemStore(db);
  const socket = fakeSocket();
  const feed = new EventFeed(new Set([socket as never]));
  const publisher = new AuctionEventPublisher(feed);
  const bidPublisher = new BidEventPublisher(feed);
  const itemService = new ItemService(store, userStoreStub(), publisher);
  const bidService = new BidService(store, bidPublisher, userStoreStub());
  return { store, socket, feed, itemService, bidService };
}

describe('UC-005 Close auction', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(START);
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.restoreAllMocks();
  });

  it('REQ-004 AC1: At the end time the item no longer accepts bids.', () => {
    const item = new Item(
      'item-1',
      'seller-1',
      'Lamp',
      10,
      'USD' as never,
      END,
      AuctionStatus.open,
      null,
      null,
      null,
    );

    expect(item.isOpen(END)).toBe(false);
  });

  it('REQ-004 AC2: The bidder with the highest bid at the end time is recorded as the winner and the winning user sees on the item page that they won.', async () => {
    const { itemService, bidService } = build();
    const listed = await itemService.listItem('seller-1', 'Lamp', 10, END, 'USD');
    await bidService.placeBid(listed.id, 'bidder-1', 15);
    await bidService.placeBid(listed.id, 'bidder-2', 20);

    vi.setSystemTime(AFTER_END);
    await itemService.closeDueAuctions(AFTER_END);

    const page = await itemService.getItem(listed.id);
    expect(page.status).toBe(AuctionStatus.closed);
    expect(page.winnerId).toBe('bidder-2');
  });

  it('REQ-004 AC3: Watchers of the item see the closed state and the winner.', async () => {
    const { itemService, bidService, socket } = build();
    const listed = await itemService.listItem('seller-1', 'Lamp', 10, END, 'USD');
    await bidService.placeBid(listed.id, 'bidder-1', 15);
    socket.send.mockClear();

    vi.setSystemTime(AFTER_END);
    await itemService.closeDueAuctions(AFTER_END);

    expect(socket.send).toHaveBeenCalled();
    const sent = socket.send.mock.calls.map((call) => String(call[0])).join(' ');
    expect(sent).toContain('closed');
    expect(sent).toContain('bidder-1');
  });

  it('REQ-004 AC4: An auction that ends with no bids is shown as unsold and has no winner.', async () => {
    const { itemService } = build();
    const listed = await itemService.listItem('seller-1', 'Lamp', 10, END, 'USD');

    vi.setSystemTime(AFTER_END);
    await itemService.closeDueAuctions(AFTER_END);

    const page = await itemService.getItem(listed.id);
    expect(page.status).toBe(AuctionStatus.unsold);
    expect(page.winnerId).toBeNull();
  });

  it('SEQ-005 scenario: Close auction', async () => {
    const { itemService, bidService, store, socket } = build();
    const listed = await itemService.listItem('seller-1', 'Lamp', 10, END, 'USD');
    await bidService.placeBid(listed.id, 'bidder-1', 15);
    socket.send.mockClear();

    const closeSpy = vi.spyOn(itemService, 'closeDueAuctions');
    const findSpy = vi.spyOn(store, 'findDueItems');
    const saveSpy = vi.spyOn(store, 'saveItem');

    const closer = new AuctionCloser(itemService, 1000);
    vi.setSystemTime(AFTER_END);
    await closer.tick();

    expect(closeSpy).toHaveBeenCalledTimes(1);
    expect(findSpy).toHaveBeenCalled();
    expect(saveSpy).toHaveBeenCalled();
    expect(socket.send).toHaveBeenCalled();

    const page = await itemService.getItem(listed.id);
    expect(page.status).toBe(AuctionStatus.closed);
    expect(page.winnerId).toBe('bidder-1');
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { Currency } from '../src/auction-api/Currency.js';
import { ItemController } from '../src/auction-api/ItemController.js';
import type { ItemView } from '../src/auction-api/ItemView.js';
import { ItemService } from '../src/auction-api/ItemService.js';
import { ExchangeRateService } from '../src/exchange-rates/ExchangeRateService.js';
import { FrankfurterClient } from '../src/exchange-rates/FrankfurterClient.js';

const ONE_HOUR_MS = 60 * 60 * 1000;

type Item = ItemView['item'];

function makeItem(): Item {
  return {
    id: 'item-1',
    title: 'Vase',
    startingPrice: 100,
    currency: 'CHF',
    highestBid: 150,
  } as unknown as Item;
}

function makeFakes(rates: Record<string, number> = { EUR: 0.5, USD: 2 }) {
  const fetchRates = vi.fn(async (_base: Currency) => ({ ...rates }));
  const frankfurterClient = { fetchRates } as unknown as FrankfurterClient;
  const exchangeRateService = new ExchangeRateService(frankfurterClient, ONE_HOUR_MS);
  const getItem = vi.fn(async (_id: string) => makeItem());
  const itemService = {
    getItem,
    listOpenItems: vi.fn(async () => []),
  } as unknown as ItemService;
  const controller = new ItemController(itemService, exchangeRateService);
  return { fetchRates, getItem, itemService, exchangeRateService, controller };
}

describe('UC-006 View prices in display currency', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2030-01-01T00:00:00Z'));
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it('REQ-005 AC1: A bidder who selects CHF, EUR or USD sees item prices and bids converted with a rate obtained from Frankfurter.', async () => {
    const { controller, fetchRates } = makeFakes({ EUR: 0.5, USD: 2 });
    const view = await controller.getItem('item-1', 'EUR');
    expect(fetchRates).toHaveBeenCalledWith(Currency.CHF);
    expect(view.displayCurrency).toBe(Currency.EUR);
    expect(view.convertedStartingPrice).toBeCloseTo(50);
    expect(view.convertedHighestBid).toBeCloseTo(75);
  });

  it('REQ-005 AC2: Only CHF, EUR and USD are offered as display currencies.', async () => {
    const { controller } = makeFakes();
    await expect(controller.getItem('item-1', 'GBP')).rejects.toThrow();
  });

  it('REQ-005 AC3: Converted prices are shown with the currency code.', async () => {
    const { controller } = makeFakes({ EUR: 0.5, USD: 2 });
    const view = await controller.getItem('item-1', 'USD');
    expect(view.displayCurrency).toBe('USD');
    expect(view.convertedStartingPrice).not.toBeNull();
  });

  it('REQ-005 AC4: Conversion is for display only: stored bids and bid validation use the item currency.', async () => {
    const { controller } = makeFakes({ EUR: 0.5, USD: 2 });
    const view = await controller.getItem('item-1', 'EUR');
    expect(view.item.currency).toBe('CHF');
    expect(view.item.startingPrice).toBe(100);
  });

  it('REQ-010 AC1: Within 1 hour of a successful fetch, no further request is made to Frankfurter for the same rates.', async () => {
    const { exchangeRateService, fetchRates } = makeFakes();
    await exchangeRateService.convert(100, Currency.CHF, Currency.EUR);
    vi.advanceTimersByTime(30 * 60 * 1000);
    await exchangeRateService.convert(100, Currency.CHF, Currency.USD);
    expect(fetchRates).toHaveBeenCalledTimes(1);
  });

  it('REQ-010 AC2: After the cache is older than 1 hour, the next conversion fetches fresh rates.', async () => {
    const { exchangeRateService, fetchRates } = makeFakes();
    await exchangeRateService.convert(100, Currency.CHF, Currency.EUR);
    vi.advanceTimersByTime(ONE_HOUR_MS + 1000);
    await exchangeRateService.convert(100, Currency.CHF, Currency.EUR);
    expect(fetchRates).toHaveBeenCalledTimes(2);
  });

  it('REQ-010 AC3: When Frankfurter cannot be reached and no valid cached rate exists, prices are shown only in the item currency and bidding still works.', async () => {
    const { controller, fetchRates, exchangeRateService } = makeFakes();
    fetchRates.mockRejectedValue(new Error('network down'));
    const view = await controller.getItem('item-1', 'EUR');
    expect(view.displayCurrency).toBeNull();
    expect(view.convertedStartingPrice).toBeNull();
    expect(view.convertedHighestBid).toBeNull();
    expect(view.item.currency).toBe('CHF');
    await expect(exchangeRateService.convert(100, Currency.CHF, Currency.EUR)).resolves.toBeNull();
  });

  it('SEQ-006 scenario: View prices in display currency', async () => {
    const { controller, getItem, fetchRates } = makeFakes({ EUR: 0.5, USD: 2 });
    const view = await controller.getItem('item-1', 'EUR');
    expect(getItem).toHaveBeenCalledWith('item-1');
    expect(fetchRates).toHaveBeenCalledTimes(1);
    expect(view.displayCurrency).toBe(Currency.EUR);
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import { DatabaseSync } from 'node:sqlite';
import { Item } from '../src/auction-api/Item.js';
import { Bid } from '../src/auction-api/Bid.js';
import { BidController } from '../src/auction-api/BidController.js';
import { BidService } from '../src/auction-api/BidService.js';
import { UserStore } from '../src/auction-api/UserStore.js';
import { ItemStore } from '../src/auction-api/ItemStore.js';
import { BidEventPublisher } from '../src/auction-api/BidEventPublisher.js';
import { EventFeed } from '../src/auction-api/EventFeed.js';
import { LiveGateway } from '../src/live-updates/LiveGateway.js';

const NOW = new Date('2030-01-01T12:00:00Z');
const ONE_HOUR_MS = 60 * 60 * 1000;
const TWO_MINUTES_MS = 2 * 60 * 1000;

function fakeSocket(): WebSocket {
  return { send: vi.fn(), readyState: 1 } as unknown as WebSocket;
}

function makeItem(overrides: { endTime?: Date; highestBidAmount?: number | null; highestBidderId?: string | null } = {}): Item {
  return new Item(
    'item-1',
    'seller-1',
    'Vase',
    100,
    'USD' as unknown as Item['currency'],
    overrides.endTime ?? new Date(NOW.getTime() + ONE_HOUR_MS),
    'open' as unknown as Item['status'],
    overrides.highestBidAmount ?? null,
    overrides.highestBidderId ?? null,
    null,
  );
}

async function setup(item: Item = makeItem()) {
  vi.useFakeTimers();
  vi.setSystemTime(NOW);
  const db = new DatabaseSync(':memory:');
  const itemStore = new ItemStore(db);
  await itemStore.saveItem(item);
  const userStore = {
    findById: async (id: string) => (id === 'unknown' ? null : { id }),
  } as unknown as UserStore;
  const feed = new EventFeed(new Set<WebSocket>());
  const publisher = new BidEventPublisher(feed);
  const service = new BidService(itemStore, publisher, userStore);
  return { itemStore, service, feed, publisher };
}

afterEach(() => {
  vi.useRealTimers();
});

describe("UC-003 Place bid", () => {
  it("REQ-002 AC1: A bid on an item whose end time has not passed, from a user other than the seller, is stored in the item currency if it is valid.", async () => {
    const { itemStore, service } = await setup();
    const bid = await service.placeBid('item-1', 'bidder-1', 150);
    const stored = await itemStore.findItem('item-1');
    expect(bid.amount).toBe(150);
    expect(stored?.currency).toBe('USD');
    expect(stored?.highestBidAmount).toBe(150);
    expect(stored?.highestBidderId).toBe('bidder-1');
  });

  it("REQ-002 AC2: A bid on an item whose end time has passed is rejected.", async () => {
    const item = makeItem({ endTime: new Date(NOW.getTime() - 1000) });
    const { service } = await setup(item);
    await expect(service.placeBid('item-1', 'bidder-1', 150)).rejects.toThrow();
  });

  it("REQ-002 AC3: The first bid is accepted only if it is at least the starting price.", async () => {
    const { service } = await setup();
    await expect(service.placeBid('item-1', 'bidder-1', 99)).rejects.toThrow();
    const bid = await service.placeBid('item-1', 'bidder-1', 100);
    expect(bid.amount).toBe(100);
  });

  it("REQ-002 AC4: Any later bid is accepted only if it is at least 1 unit of the item currency higher than the current highest bid, otherwise it is rejected.", async () => {
    const item = makeItem({ highestBidAmount: 200, highestBidderId: 'bidder-0' });
    const { service } = await setup(item);
    await expect(service.placeBid('item-1', 'bidder-1', 200)).rejects.toThrow();
    const bid = await service.placeBid('item-1', 'bidder-1', 201);
    expect(bid.amount).toBe(201);
  });

  it("REQ-002 AC5: A bid by the item's seller on their own item is rejected.", async () => {
    const { service } = await setup();
    await expect(service.placeBid('item-1', 'seller-1', 150)).rejects.toThrow();
  });

  it("REQ-009 AC1: A valid bid placed less than or exactly 2 minutes before the end time moves the end time 2 minutes later.", async () => {
    const endTime = new Date(NOW.getTime() + 10 * 60 * 1000);
    const item = makeItem({ endTime });
    const now = new Date(endTime.getTime() - TWO_MINUTES_MS);
    const extended = item.extendIfLate(now);
    expect(extended).toBe(true);
    expect(item.endTime.getTime()).toBe(endTime.getTime() + TWO_MINUTES_MS);
  });

  it("REQ-009 AC2: A valid bid placed more than 2 minutes before the end time does not change the end time.", async () => {
    const endTime = new Date(NOW.getTime() + 10 * 60 * 1000);
    const item = makeItem({ endTime });
    const now = new Date(endTime.getTime() - 5 * 60 * 1000);
    const extended = item.extendIfLate(now);
    expect(extended).toBe(false);
    expect(item.endTime.getTime()).toBe(endTime.getTime());
  });

  it.todo("REQ-009 AC3: manual: watching browsers rendering the new end time needs a real browser session.");

  it("REQ-003 AC1: When a bid is accepted, every client watching the item shows the new bid without a page reload.", () => {
    const gateway = new LiveGateway(new Map<string, WebSocket>());
    const sockets = [fakeSocket(), fakeSocket(), fakeSocket()];
    sockets.forEach((socket, index) => {
      gateway.sockets.set(`client-${index}`, socket);
      gateway.watch(`client-${index}`, 'item-1');
    });
    gateway.broadcast('item-1', 'bid:150');
    for (const socket of sockets) {
      expect(socket.send).toHaveBeenCalledWith('bid:150');
    }
  });

  it("REQ-003 AC2: A client watching a different item does not receive that bid.", () => {
    const gateway = new LiveGateway(new Map<string, WebSocket>());
    const watcher = fakeSocket();
    const other = fakeSocket();
    gateway.sockets.set('client-a', watcher);
    gateway.sockets.set('client-b', other);
    gateway.watch('client-a', 'item-1');
    gateway.watch('client-b', 'item-2');
    gateway.broadcast('item-1', 'bid:150');
    expect(watcher.send).toHaveBeenCalledWith('bid:150');
    expect(other.send).not.toHaveBeenCalled();
  });

  it.todo("REQ-003 AC3: manual: refreshing the open items list in a browser needs a real page session.");

  it.todo("REQ-003 AC4: manual: retry of the live update configuration load needs a browser with a flaky network.");

  it("REQ-011 AC1: With 200 clients watching one item and a few bids per second, each accepted bid appears on every client within 1 second.", () => {
    const gateway = new LiveGateway(new Map<string, WebSocket>());
    const sockets: WebSocket[] = [];
    for (let index = 0; index < 200; index += 1) {
      const socket = fakeSocket();
      sockets.push(socket);
      gateway.sockets.set(`client-${index}`, socket);
      gateway.watch(`client-${index}`, 'item-1');
    }
    gateway.broadcast('item-1', 'bid:150');
    for (const socket of sockets) {
      expect(socket.send).toHaveBeenCalledWith('bid:150');
    }
  });

  it.todo("REQ-011 AC2: manual: confirming no accepted bid is lost under sustained load needs a live load test environment.");

  it("SEQ-003 scenario: Place bid", async () => {
    const { itemStore, service, feed } = await setup();
    const publish = vi.spyOn(feed, 'publish');
    const controller = new BidController(service);
    const bid = await controller.placeBid('item-1', 'bidder-1', 150);
    expect(bid).toBeInstanceOf(Bid);
    expect(bid.itemId).toBe('item-1');
    expect(bid.bidderId).toBe('bidder-1');
    expect(bid.amount).toBe(150);
    const stored = await itemStore.findItem('item-1');
    expect(stored?.highestBidAmount).toBe(150);
    expect(stored?.highestBidderId).toBe('bidder-1');
    expect(publish).toHaveBeenCalledTimes(1);
  });
});

import { describe, expect, it } from 'vitest';
import { LiveGateway } from '../src/live-updates/LiveGateway.js';
import { EventFeedClient } from '../src/live-updates/EventFeedClient.js';

type SocketMap = ConstructorParameters<typeof LiveGateway>[0];
type SocketValue = SocketMap extends Map<string, infer S> ? S : never;

function fakeSocket(): { socket: SocketValue; received: string[] } {
  const received: string[] = [];
  const socket = {
    readyState: 1,
    send: (message: string) => {
      received.push(message);
    },
  };
  return { socket: socket as unknown as SocketValue, received };
}

describe('UC-004 Watch item live', () => {
  it.todo('REQ-007 AC1: With two or more live update server instances running, a client connected to any instance receives every bid for the item it watches.');

  it.todo('REQ-007 AC2: Adding an instance requires no code change.');

  it('SEQ-004 scenario: Watch item live', () => {
    const { socket, received } = fakeSocket();
    const sockets = new Map<string, SocketValue>([['client-1', socket]]) as unknown as SocketMap;
    const gateway = new LiveGateway(sockets);
    const eventFeedClient = new EventFeedClient(gateway);

    // 1. User -> LiveGateway: watch
    gateway.watch('client-1', 'item-1');

    // 2. EventFeed -> EventFeedClient: onEvent
    // 3. EventFeedClient -> LiveGateway: broadcast to watching browsers
    eventFeedClient.onEvent('bid', 'item-1:bid-42');
    expect(received.length).toBe(1);
    expect(received[0]).toContain('item-1');

    // 4. User -> LiveGateway: unwatch
    gateway.unwatch('client-1', 'item-1');
    eventFeedClient.onEvent('bid', 'item-1:bid-43');
    expect(received.length).toBe(1);
  });
});

